def compress_ranges(nums):
    unique = sorted(set(nums))
    if not unique:
        return []
    ranges = []
    start = unique[0]
    prev = unique[0]
    for num in unique[1:]:
        if num == prev + 1:
            prev = num
        else:
            ranges.append((start, prev))
            start = num
            prev = num
    ranges.append((start, prev))
    return ranges
